package dev.gamersclt.batcaverna.nativeapp;
import org.json.*;import org.junit.Test;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import java.lang.reflect.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35,manifest=Config.NONE)
public class NativePresenceStateTest {
 @Test public void replacementAndDisconnectCannotLeaveAnOldGame()throws Exception{NativePresence presence=new NativePresence(RuntimeEnvironment.getApplication());JSONObject[] snapshot={null};presence.listen((state,connected)->snapshot[0]=state);Method receive=NativePresence.class.getDeclaredMethod("receive",String.class);receive.setAccessible(true);receive.invoke(presence,frame("presence_state",new JSONObject("{\"friend\":{\"metas\":[{\"phx_ref\":\"old\",\"jogo\":\"Control\",\"status\":\"online\"}]}}")));assertEquals("Control",snapshot[0].getJSONObject("friend").getJSONArray("metas").getJSONObject(0).getString("jogo"));receive.invoke(presence,frame("presence_diff",new JSONObject("{\"joins\":{\"friend\":{\"metas\":[{\"phx_ref\":\"new\",\"phx_ref_prev\":\"old\",\"jogo\":\"\",\"status\":\"online\"}]}},\"leaves\":{\"friend\":{\"metas\":[{\"phx_ref\":\"old\"}]}}}")));JSONArray metas=snapshot[0].getJSONObject("friend").getJSONArray("metas");assertEquals(1,metas.length());assertEquals("",metas.getJSONObject(0).getString("jogo"));Method lost=NativePresence.class.getDeclaredMethod("lost",int.class);lost.setAccessible(true);lost.invoke(presence,0);assertEquals(0,snapshot[0].length());}
 private String frame(String event,JSONObject payload)throws Exception{return new JSONObject().put("topic","realtime:platinados-presenca").put("event",event).put("payload",payload).toString();}
}
